```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let seconds = wall_clock::now().seconds;

        // A transport failure arrives as a value; a request outside the
        // allowlist would trap at the boundary instead.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let message = format!("heartbeat at {seconds}: fetched {fetched} chars");
        let accepted = notifier::notify(&message);

        // The contract requires notified == true on every output. If the
        // notifier refused, no conforming report exists, so refuse to emit one.
        if !accepted {
            panic!("notifier refused the digest notification; ensures notified == true cannot hold");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified: true,
        }
    }
}

export!(Node);
